// ---------------------------------------------------------------------------
// Stake units. The queued word stores the stake per spin as a whole number of
// units — ETH_STAKE_UNIT (1 gwei on mainnet) or FLIP_STAKE_UNIT (1 whole FLIP)
// — and placement reverts InvalidBet on any amount that is not a whole unit.
// The ETH unit is an ETH literal, so the testnet overlay rescales it with every
// other ETH amount (1 gwei / 1e6 = 1,000 wei); derive it from ETH_DIVISOR
// instead of pinning one network's value.
// ---------------------------------------------------------------------------

const ETH_STAKE_UNIT_FULL_SCALE = 10n ** 9n;
// One whole FLIP, in token wei (the UI's FLIP unit; app/app/token-units.js). The word stores whole
// FLIP on every deployment (FLIP_STAKE_UNIT was 1 ether before audit b05ea7c50, 1 after).
const FLIP_STAKE_UNIT = TOKEN_WEI;

/** Chain-scale stake unit for a bet currency, or null when unsupported. */
export function degeneretteStakeUnit(currency) {
  const cur = Number(currency);
  if (cur === DEGENERETTE_CURRENCY.FLIP) return FLIP_STAKE_UNIT;
  if (cur !== DEGENERETTE_CURRENCY.ETH) return null;
  const divisor = BigInt(ETH_DIVISOR);
  const unit = divisor > 0n ? ETH_STAKE_UNIT_FULL_SCALE / divisor : ETH_STAKE_UNIT_FULL_SCALE;
  return unit > 0n ? unit : 1n;
}

/**
 * Floor an amount per spin to a whole stake unit so a placement can never
 * revert InvalidBet on granularity. Returns null for an unsupported currency
 * or a non-numeric amount.
 */
export function floorDegeneretteStake(amountPerSpin, currency) {
  const unit = degeneretteStakeUnit(currency);
  if (unit == null) return null;
  let amount;
  try { amount = BigInt(amountPerSpin); } catch (_e) { return null; }
  if (amount <= 0n) return 0n;
  return amount - (amount % unit);
}

// ---------------------------------------------------------------------------
// Queued bet word (degeneretteQueue[index][betId - 1], also DegeneretteBetPlaced
// .packed), LSB → MSB: owner[0..159] | symbol[160..164] | spinCount[165..169] |
// currency[170] | record flag[171] | activity[172..187] | boosted stake per spin
// in units[188..251] | reserved[252..255].
// ---------------------------------------------------------------------------

const MASK_160 = (1n << 160n) - 1n;
const MASK_64 = (1n << 64n) - 1n;
const BET_SYMBOL_SHIFT = 160n;
const BET_COUNT_SHIFT = 165n;
const BET_CURRENCY_SHIFT = 170n;
const BET_RECORD_SHIFT = 171n;
const BET_ACTIVITY_SHIFT = 172n;
const BET_STAKE_SHIFT = 188n;

/**
 * Decode one queued bet word. `amountPerSpin` is chain-scale (units × stake
 * unit) and already includes any stake-boon bonus the contract floored in.
 * Returns null for a zero/non-numeric word (resolved or unknown).
 */
export function decodeDegeneretteBetWord(packed) {
  let p;
  try { p = BigInt(packed ?? 0); } catch (_e) { return null; }
  if (p <= 0n) return null;
  const symbol = Number((p >> (BET_SYMBOL_SHIFT - (hasWalletIds() ? 128n : 0n))) & 0x1Fn);
  const currency = Number((p >> (BET_CURRENCY_SHIFT - (hasWalletIds() ? 128n : 0n))) & 1n);
  const stakeUnits = (p >> (BET_STAKE_SHIFT - (hasWalletIds() ? 128n : 0n))) & MASK_64;
  const unit = degeneretteStakeUnit(currency) ?? 0n;
  return {
    ...(hasWalletIds() ? { playerId: Number(p & 0xffffffffn), owner: null } : { owner: `0x${(p & MASK_160).toString(16).padStart(40, '0')}` }),
    symbol,
    heroQuadrant: symbol >> 3,
    spinCount: Number((p >> (BET_COUNT_SHIFT - (hasWalletIds() ? 128n : 0n))) & 0x1Fn),
    currency,
    recordArmed: ((p >> (BET_RECORD_SHIFT - (hasWalletIds() ? 128n : 0n))) & 1n) === 1n,
    activityScore: Number((p >> (BET_ACTIVITY_SHIFT - (hasWalletIds() ? 128n : 0n))) & 0xFFFFn),
    stakeUnits,
    ...(!hasDegeneretteWilds() ? {boonTier:Number((p >> 252n) & 3n)} : {}),
    amountPerSpin: stakeUnits * unit,
  };
}

/**
 * The contract's unique, placement-ordered identity for a bet: the same
 * `(index << 64) | betId` key degeneretteRecordBounty uses. Null when either
 * half is missing.
 */
const MAX_PAID_PAYOUT_X = 1_000_000n;
const DEGENERETTE_BOON_ETH_CAP_FULL_SCALE = 10n * 10n ** 18n;
const DEGENERETTE_BOON_FLIP_CAP = 100_000n * 10n ** 18n;
export function degenerettePaidStakePerSpin(packed) {
  const bet = decodeDegeneretteBetWord(packed);
  if (!bet) return null;
  const unit = degeneretteStakeUnit(bet.currency);
  if (!unit) return null;
  let units = bet.stakeUnits;
  const boonBps = BigInt(bet.boonTier) * 400n;
  if (boonBps !== 0n && bet.spinCount > 0) {
    const divisor = BigInt(ETH_DIVISOR);
    const cap = bet.currency === DEGENERETTE_CURRENCY.ETH
      ? (divisor > 0n ? DEGENERETTE_BOON_ETH_CAP_FULL_SCALE / divisor : DEGENERETTE_BOON_ETH_CAP_FULL_SCALE)
      : DEGENERETTE_BOON_FLIP_CAP;
    const cappedBonus = (((cap / unit) * boonBps) / 10_000n) / BigInt(bet.spinCount);
    const fromCap = units > cappedBonus ? units - cappedBonus : 0n;
    const fromRate = (units * 10_000n + 10_000n + boonBps - 1n) / (10_000n + boonBps);
    units = fromCap > fromRate ? fromCap : fromRate;
  }
  return units * unit;
}

/**
 * _capPaidBetPayout: a paid bet's 9/9 payout never exceeds 1,000,000x its paid
 * stake. ETH's gross includes the lootbox leg; FLIP caps at half, before the
 * survival double. Only score 9 can reach it.
 */
export function capDegenerettePaidPayout(packed, payout) {
  if (hasDegeneretteWilds()) return BigInt(payout ?? 0);
  let amount;
  try { amount = BigInt(payout ?? 0); } catch (_e) { return 0n; }
  const paid = degenerettePaidStakePerSpin(packed);
  if (paid == null) return amount;
  const bet = decodeDegeneretteBetWord(packed);
  let ceiling = paid * MAX_PAID_PAYOUT_X;
  if (bet.currency === DEGENERETTE_CURRENCY.FLIP) ceiling /= 2n;
  return amount > ceiling ? ceiling : amount;
}


export function degeneretteBetKey(index, betId) {
  if (index == null || betId == null) return null;
  try {
    const i = BigInt(index);
    const b = BigInt(betId);
    if (i < 0n || b < 0n || b > MASK_64) return null;
    return (i << 64n) | b;
  } catch (_e) {
    return null;
  }
}

/**
 * Unpack DegeneretteResolved.spins: 5 bytes per spin, spin 0 first — the
 * player's lanes (4 bytes, big-endian), then score S (bits 0-3) | house wild
 * count W (bits 4-6). Accepts a 0x hex string or a byte array.
 *
 * @returns {Array<{spinIndex:number, playerTraits:number, score:number, wilds:number}>|null}
 */
export function decodeDegeneretteSpins(spins) {
  let bytes;
  if (spins instanceof Uint8Array) bytes = spins;
  else if (Array.isArray(spins)) bytes = Uint8Array.from(spins);
  else {
    const hex = String(spins ?? '').replace(/^0x/i, '');
    if (hex.length % 2 !== 0 || /[^0-9a-f]/i.test(hex)) return null;
    bytes = new Uint8Array(hex.length / 2);
    for (let i = 0; i < bytes.length; i += 1) bytes[i] = parseInt(hex.slice(i * 2, i * 2 + 2), 16);
  }
  if (bytes.length === 0 || bytes.length % 5 !== 0) return null;
  const out = [];
  for (let i = 0; i < bytes.length / 5; i += 1) {
    const at = i * 5;
    const tail = bytes[at + 4];
    out.push({
      spinIndex: i,
      playerTraits: ((bytes[at] << 24) | (bytes[at + 1] << 16) | (bytes[at + 2] << 8) | bytes[at + 3]) >>> 0,
      score: tail & 0x0F,
      ...(hasDegeneretteWilds() ? { wilds: (tail >> 4) & 0x07 } : { goldMatches: (tail >> 4) & 0x07 }),
    });
  }
  return out;
}

// ---------------------------------------------------------------------------
// Exact payout-table projection.
//
// These constants and integer operations mirror DegenerusGameDegeneretteModule
// `_degenerettePayout` (checked by scripts/data/degenerette_single_symbol_math.py
// and the shared degenerette-wild-vectors fixture). The contract has no public
// quote method, so keeping this pure projection beside the canonical write ABI
// lets the hidden rules sheet show the schedule for the currency and activity
// score the player is actually about to submit.
//
// ONE base table serves every score 3..9 (scores 0-2 pay nothing), scaled by
// `(4 + wilds) / 4` — +25% per wild lane on the HOUSE ticket. `wilds` is a
// property of the RESOLVED spin, so callers that don't yet know the outcome
// pass 0 (the guaranteed floor). ETH adds a flat return on S6-S9; WWXRP keeps
// its own S8/S9 prizes and a fixed pre-scaled floor with an activity bonus.
// ---------------------------------------------------------------------------

// Centi-x, indexed by score S0..S9.
const BASE_CENTIX = [0n, 0n, 0n, 50n, 300n, 1_000n, 10_000n, 62_500n, 1_817_328n, 23_000_000n];
// ETH's flat additions in centi-x, S0..S9, not scaled by activity.
const ETH_ADD_CENTIX = [0n, 0n, 0n, 0n, 0n, 0n, 240n, 4_600n, 105_000n, 22_408_400n];
const WWXRP_PAYOUT_S8 = 480_677n;
const WWXRP_PAYOUT_S9 = 100_000_000n;
const WWXRP_FLOOR_SCALED = 5_762_468_903n;
const WWXRP_BONUS_FACTORS = [0n, 0n, 0n, 0n, 0n, 0n, 356_636n, 1_825_147n, 5_245_201n, 2_242_955n];
const ROI_MIN_BPS = 9_000n;
const ROI_VA_BPS = 9_891n;
const ROI_VB_BPS = 9_970n;
const ROI_MAX_BPS = 9_990n;
const WWXRP_ROI_MIN_BPS = 7_000n;
const WWXRP_ROI_VA_BPS = 12_400n;
const WWXRP_ROI_VB_BPS = 12_760n;
const WWXRP_ROI_MAX_BPS = 13_000n;

const ETH_FLIP_DIVISOR = 4_000_000n; // 100 (centi) x 4 (wild ratio) x 10^4 (bps)
const WWXRP_DIVISOR = 4_000_000_000_000n; // 100 x 4 x 10^10 (scaled bps)
const MAX_WILDS = 4;
// ActivityCurveLib knees.
const ACTIVITY_K = 305n;
const ACTIVITY_KNEE = 500n;
const ACTIVITY_CAP = 30_000n;

function _curve(score, min, valueA, valueB, max) {
  const s = score < 0n ? 0n : score;
  if (s >= ACTIVITY_CAP) return max;
  if (s <= ACTIVITY_K) return min + (s * (valueA - min)) / ACTIVITY_K;
  if (s <= ACTIVITY_KNEE) {
    return valueA + ((s - ACTIVITY_K) * (valueB - valueA)) / (ACTIVITY_KNEE - ACTIVITY_K);
  }
  return valueB + ((s - ACTIVITY_KNEE) * (max - valueB)) / (ACTIVITY_CAP - ACTIVITY_KNEE);
}

/**
 * Exact gross-return schedule for one Degenerette currency/activity/wild-count
 * combination. `multiplierHundredths` is rounded only for display;
 * `multiplierNumerator`/`multiplierDenominator` retain the contract's exact
 * fraction: ETH/FLIP `(base x roiBps + ethAdd x 10^4) x (4+wilds) / 4e6`, WWXRP
 * `base x (4+wilds) x scaled / 4e12`.
 *
 * @param {{currency?: number, activityScore?: number|bigint,
 *           wilds?: number}} args `wilds` (0-4) is the number of wild lanes
 *           on the house ticket — unknowable before resolution, so callers
 *           previewing a bet should leave it at the default 0 (the floor).
 */
export function degenerettePayoutTable({
  currency = DEGENERETTE_CURRENCY.ETH,
  activityScore = 0,
  wilds = 0,
  goldMatches = 0,
} = {}) {
  if (!hasDegeneretteWilds()) return legacyPayoutTable({ currency, activityScore, goldMatches });
  const cur = Number(currency);
  if (![DEGENERETTE_CURRENCY.ETH, DEGENERETTE_CURRENCY.FLIP, DEGENERETTE_CURRENCY.WWXRP].includes(cur)) {
    throw new Error('Unsupported Degenerette currency.');
  }
  let activity;
  try { activity = BigInt(activityScore); }
  catch (_e) { activity = 0n; }
  if (activity < 0n) activity = 0n;
  let wildCount = Number(wilds);
  if (!Number.isInteger(wildCount)) wildCount = 0;
  if (wildCount < 0) wildCount = 0;
  if (wildCount > MAX_WILDS) wildCount = MAX_WILDS;
  const ratio = BigInt(4 + wildCount);

  const isWwxrp = cur === DEGENERETTE_CURRENCY.WWXRP;
  const rows = [];
  for (let score = 0; score <= 9; score += 1) {
    let basePayoutCentiX = BASE_CENTIX[score];
    let multiplierNumerator = 0n;
    let multiplierDenominator = ETH_FLIP_DIVISOR;
    if (score >= 3) {
      if (isWwxrp) {
        if (score === 8) basePayoutCentiX = WWXRP_PAYOUT_S8;
        else if (score === 9) basePayoutCentiX = WWXRP_PAYOUT_S9;
        let scaled = WWXRP_FLOOR_SCALED;
        if (score >= 6) {
          scaled += (_curve(activity, WWXRP_ROI_MIN_BPS, WWXRP_ROI_VA_BPS, WWXRP_ROI_VB_BPS, WWXRP_ROI_MAX_BPS)
            - WWXRP_ROI_MIN_BPS) * WWXRP_BONUS_FACTORS[score];
        }
        multiplierNumerator = basePayoutCentiX * ratio * scaled;
        multiplierDenominator = WWXRP_DIVISOR;
      } else {
        const roiBps = _curve(activity, ROI_MIN_BPS, ROI_VA_BPS, ROI_VB_BPS, ROI_MAX_BPS);
        const add = cur === DEGENERETTE_CURRENCY.ETH ? ETH_ADD_CENTIX[score] : 0n;
        multiplierNumerator = (basePayoutCentiX * roiBps + add * 10_000n) * ratio;
      }
    }
    rows.push(Object.freeze({
      score,
      basePayoutCentiX,
      multiplierNumerator,
      multiplierDenominator,
      multiplierHundredths: (multiplierNumerator * 100n + multiplierDenominator / 2n) / multiplierDenominator,
    }));
  }
  return Object.freeze({
    currency: cur,
    activityScore: activity,
    wilds: wildCount,
    rows: Object.freeze(rows),
  });
}

/** Format `multiplierHundredths` without crossing through lossy Number math. */
export function formatDegeneretteMultiplier(multiplierHundredths) {
  let value;
  try { value = BigInt(multiplierHundredths); } catch (_e) { return '—'; }
  const whole = value / 100n;
  const cents = value % 100n;
  if (value === 0n) return '0×';
  return `${whole.toLocaleString('en-US')}.${cents.toString().padStart(2, '0')}×`;
}

/**
 * One settled spin's payout, exactly as _degenerettePayout computes it:
 * `amountPerSpin × table(S, wilds)` with the row's exact fraction. This is the
 * gross the spin produced before the ETH 3-tier split / pool cap and before a FLIP
 * bet's survival flip — the value the retired DegeneretteResult.payout carried.
 */
export function degeneretteSpinPayout({
  currency,
  amountPerSpin,
  activityScore = 0,
  score,
  wilds = 0,
  goldMatches = 0,
} = {}) {
  let stake;
  try { stake = BigInt(amountPerSpin ?? 0); } catch (_e) { return 0n; }
  const s = Number(score);
  if (stake <= 0n || !Number.isInteger(s) || s < 0 || s > 9) return 0n;
  const row = degenerettePayoutTable({ currency, activityScore, wilds, goldMatches }).rows[s];
  if (!row || row.multiplierNumerator === 0n) return 0n;
  // A FLIP bet's spin is priced in the chain's own units: whole FLIP since audit b05ea7c50, so
  // each spin's payout floors to a whole token before the survival flip (token wei out).
  if (Number(currency) === DEGENERETTE_CURRENCY.FLIP) {
    return flipFromChain((flipToChain(stake) * row.multiplierNumerator) / row.multiplierDenominator);
  }
  return (stake * row.multiplierNumerator) / row.multiplierDenominator;
}

/**
 * DegeneretteResolved.totalPayout is in its bet's currency: ETH wei, or a FLIP amount (whole FLIP
 * since audit b05ea7c50). The event carries no currency, so the bet word decides; the result is
 * wei for ETH and token wei for FLIP. Unknown words leave the value untouched.
 */
export function degeneretteTotalPayoutFromChain(totalPayout, packed) {
  let value;
  try { value = BigInt(totalPayout ?? 0); } catch (_e) { return 0n; }
  return decodeDegeneretteBetWord(packed)?.currency === DEGENERETTE_CURRENCY.FLIP ? flipFromChain(value) : value;
}

/**
 * Expand a DegeneretteResolved entry into per-spin rows — the shape the retired
 * DegeneretteResult rows had ({spinIndex, playerTraits, matches, payout}) plus
 * index/wilds — pricing each spin from the bet word. Returns null when
 * the spins cannot be decoded or the word is unknown (a payout guessed without
 * the stake would misstate every hit).
 */
export function degeneretteSpinResults(resolvedEntry, packed) {
  const bet = decodeDegeneretteBetWord(packed);
  if (!resolvedEntry || !bet) return null;
  const spins = Array.isArray(resolvedEntry.spins)
    ? resolvedEntry.spins
    : decodeDegeneretteSpins(resolvedEntry.spins ?? resolvedEntry.spinsData);
  if (!Array.isArray(spins) || spins.length === 0) return null;
  let betId = null;
  let index = null;
  try { if (resolvedEntry.betId != null) betId = BigInt(resolvedEntry.betId); } catch (_e) { betId = null; }
  try { if (resolvedEntry.index != null) index = BigInt(resolvedEntry.index); } catch (_e) { index = null; }
  const player = String(resolvedEntry.player ?? bet.owner ?? '');
  return spins.map((spin) => {
    const gross = degeneretteSpinPayout({
      currency: bet.currency,
      amountPerSpin: bet.amountPerSpin,
      activityScore: bet.activityScore,
      score: spin.score,
      wilds: spin.wilds,
      goldMatches: spin.goldMatches,
    });
    return {
      player,
      index,
      betId,
      spinIndex: BigInt(spin.spinIndex),
      playerTraits: BigInt(spin.playerTraits),
      matches: BigInt(spin.score),
      ...(hasDegeneretteWilds() ? { wilds: BigInt(spin.wilds ?? 0) } : { goldMatches: BigInt(spin.goldMatches ?? 0) }),
      payout: !hasDegeneretteWilds() && spin.score === 9 ? capDegenerettePaidPayout(packed, gross) : gross,
    };
  });
}

// ---------------------------------------------------------------------------
// Test seam — production path uses default `new ethers.Contract(...)`.
// degenerette is delegate-called via DegenerusGame, so factory points at
// CONTRACTS.GAME (not a separate degenerette address).
// ---------------------------------------------------------------------------

let _contractFactory = null;
const _resolvedBetCache = new Map();
const _resolvedBetInflight = new Map();

/** Test-only: replace the `new Contract(...)` construction with a fake. */
export function __setContractFactoryForTest(fn) {
  _contractFactory = fn;
  _resolvedBetCache.clear();
  _resolvedBetInflight.clear();
}

/** Test-only: clear the injected factory; subsequent calls use the real path. */
export function __resetContractFactoryForTest() {
  _contractFactory = null;
  _resolvedBetCache.clear();
  _resolvedBetInflight.clear();
}

function _readProvider() {
  return permissionlessReadProvider(getProvider());
}

function _buildContract(signerOrProvider) {
  if (_contractFactory) return _contractFactory(signerOrProvider);
  return new ethers.Contract(CONTRACTS.GAME, walletAbi(DEGENERETTE_ABI, run66GAME), signerOrProvider);
}

// ---------------------------------------------------------------------------
// Receipt parsing — the parse* helpers below take a parser-shaped object so
// tests can inject one. Callers that have no Contract handle should pass
// NOTHING and get receiptParser(), which decodes real logs off this module's
// own ABI. The panel used to hand in `{interface:{parseLog: (log) => log.parsed
// ?? null}}` — a test seam that returns null for every production log, so no
// resolve outcome was ever parsed on-chain (fixed 2026-07-29).
// ---------------------------------------------------------------------------

let _iface = null;
let _ifaceIds = null;
let _recordIface = null;
let _recordIfaceIds = null;

function _interface() {
  if (!_iface || _ifaceIds !== hasWalletIds()) { _iface = new ethers.Interface(walletAbi(DEGENERETTE_ABI, run66GAME)); _ifaceIds = hasWalletIds(); }
  return _iface;
}

function _recordInterface() {
  if (!_recordIface || _recordIfaceIds !== hasWalletIds()) { _recordIface = new ethers.Interface(walletAbi(RECORD_EVENT_ABI, run66COINFLIP)); _recordIfaceIds = hasWalletIds(); }
  return _recordIface;
}

/** Default log parser: real ABI decode, with the fakeDOM `log.parsed` seam. */
export function receiptParser() {
  return {
    interface: {
      parseLog: (log) => {
        if (log && log.parsed) return log.parsed;
        try { return walletReceiptLog(log, _interface()); } catch (_e) { return null; }
      },
    },
  };
}

// ---------------------------------------------------------------------------
// Structured-revert-error helper — verbatim port from claims.js / passes.js / coinflip.js.
// ---------------------------------------------------------------------------

function _structuredRevertError(error, context) {
  const decoded = decodeRevertReason(error);
  const wrapped = new Error(decoded.userMessage || `Failed: ${context}`);
  wrapped.code = decoded.code;
  wrapped.userMessage = decoded.userMessage;
  wrapped.recoveryAction = decoded.recoveryAction;
  wrapped.cause = error;
  return wrapped;
}

// ---------------------------------------------------------------------------
// placeBet — BUY-05 stage 1 — placeDegeneretteBet (payable).
//
// Validates inputs client-side (defense-in-depth before static-call):
//   - currency ∈ {ETH (0), FLIP (1)} — anything else reverts UnsupportedCurrency.
//   - ticketCount ∈ [1, per-currency cap].
//   - amountPerTicketWei > 0n, floored to a whole stake unit, ≥ the minimum.
//   - symbol ∈ [0, 23] (quadrant = symbol >> 3, icon = symbol & 7); defaults
//     to 0 if not provided. DegeneretteModule reverts InvalidBet when
//     symbol >= DEGENERETTE_HERO_COUNT.
// ---------------------------------------------------------------------------

/**
 * @param {{
 *   currency: number,
 *   amountPerTicketWei: bigint | string | number,
 *   ticketCount: number,
 *   symbol?: number,
 *   msgValueWei?: bigint | string | number,
 *   preferClaimable?: boolean,
 *   player?: string,
 *   onSubmitted?: function(import('ethers').TransactionResponse): void,
 * }} args
 * @returns {Promise<{receipt: import('ethers').TransactionReceipt}>}
 */
export async function placeBet({
  currency,
  amountPerTicketWei,
  ticketCount,
  symbol,
  msgValueWei,
  preferClaimable = false,
  player,
  onSubmitted,
} = {}) {
  const buyer = player || getActingAddress();
  if (!buyer) throw new Error('Wallet not connected.');

  // Currency validation — explicit allow-list. The contract takes ETH (0) and
  // FLIP (1) only; anything else reverts UnsupportedCurrency.
  const cur = Number(currency);
  const limits = degeneretteLimits(cur);
  if (!limits) {
    throw new Error('Unsupported currency. Pick ETH or FLIP.');
  }

  // Spin count — the contract's per-currency cap, not a flat one.
  const tc = Number(ticketCount);
  if (!Number.isInteger(tc) || tc < SPINS_MIN || tc > limits.maxSpins) {
    throw new Error(`Cards must be ${SPINS_MIN}-${limits.maxSpins} for ${limits.unit}.`);
  }

  // Amount per spin: a whole number of stake units (the contract reverts
  // InvalidBet on anything finer, so sub-unit dust is floored off here rather
  // than sent), and ≥ the contract's per-currency minimum. Callers hand ETH in
  // the CHAIN's wei scale, so multiplying by ETH_DIVISOR recovers the
  // full-scale figure the minimum is written in — exact on both chains.
  let requested;
  try {
    requested = BigInt(amountPerTicketWei);
  } catch (_e) {
    throw new Error('Amount must be a numeric value.');
  }
  if (requested <= 0n) {
    throw new Error('Amount must be greater than 0.');
  }
  const amount = floorDegeneretteStake(requested, cur);
  const fullScale = cur === DEGENERETTE_CURRENCY.ETH ? amount * BigInt(ETH_DIVISOR) : amount;
  if (amount <= 0n || fullScale < limits.minBetFullScale) {
    throw new Error(`Minimum bet is ${limits.minLabel} ${limits.unit} per card.`);
  }

  const sym = symbol == null ? SYMBOL_DEFAULT : Number(symbol);
  if (!Number.isInteger(sym) || sym < 0 || sym >= DEGENERETTE_HERO_COUNT) {
    throw new Error('Choose a Crypto, Zodiac, or Cards symbol. Dice cannot be heroes.');
  }
  const totalBet = amount * BigInt(tc);
  // The calldata stake: ETH as given; FLIP in the deployment's raw units (whole FLIP since audit
  // b05ea7c50 — `amount` is token wei, already floored to a whole token above).
  const amountArg = cur === DEGENERETTE_CURRENCY.FLIP ? flipToChain(amount) : amount;

  const provider = getProvider();
  const signer = provider ? await provider.getSigner() : null;
  const signerContract = signer ? _buildContract(signer) : null;
  let payment = claimableFirstPayment(totalBet, 0n);
  if (cur === DEGENERETTE_CURRENCY.ETH && preferClaimable && signerContract
    && typeof signerContract.claimableWinningsOf === 'function') {
    try {
      payment = claimableFirstPayment(
        totalBet,
        await signerContract.claimableWinningsOf(buyer),
      );
    } catch (_e) {
      // A quote failure must not strand the wager. Sending the full amount is
      // the safe fallback; the static-call remains the authoritative gate.
      payment = claimableFirstPayment(totalBet, 0n);
    }
  }
  const value = cur === DEGENERETTE_CURRENCY.ETH
    ? (preferClaimable ? payment.msgValueWei : BigInt(msgValueWei ?? totalBet))
    : BigInt(msgValueWei ?? 0n);

  // Static-call gate (Phase 56 D-05) — runs only if a signer is available.
  if (signer) {
    const sim = await requireStaticCall(
      signerContract,
      'placeDegeneretteBet',
      // The ETH lane is payable. Simulating it without the same value override
      // makes every otherwise-valid ETH bet revert in preflight even though
      // the real send below is correctly funded. The FLIP lane carries
      // value=0, so one canonical argument list is safe for both currencies.
      [await accountArg(buyer), cur, amountArg, tc, sym, { value }],
      signer,
    );
    if (!sim.ok) throw _structuredRevertError(sim.error, 'static-call placeDegeneretteBet');
  }

  // Phase 58 chokepoint — closure form mandatory.
  const receipt = await sendTx(
    async (s) => _buildContract(s).placeDegeneretteBet(await accountArg(buyer), cur, amountArg, tc, sym, { value }),
    'Place degenerette bet',
    { onSubmitted },
  );
  return { receipt, payment: { ...payment, msgValueWei: value }, amountPerSpin: amount };
}

// ---------------------------------------------------------------------------
// resolveBets — OPTIONAL early settle. Bets settle automatically on the next
// mineFlip() crank once their index's word lands. There is no per-bet door
// since audit 2525eb7fd, and audit 18490c6fe removed the openBoxes(maxCount)
// valve: this sends one mineFlip(), whose stages settle in order everything
// queued ahead of the bet first (and pay the caller the miner bounty).
// `settled` reports whether this call reached the bets.
// ---------------------------------------------------------------------------

function _uint48(value, label) {
  let n;
  try { n = BigInt(value); } catch (_e) { throw new Error(`${label} must be numeric.`); }
  if (n < 0n || n >= (1n << 48n)) throw new Error(`${label} is out of range.`);
  return n;
}

/**
 * @param {{index: bigint|number|string, betIds: Array<bigint | number | string>}} args
 * @returns {Promise<{receipt: import('ethers').TransactionReceipt, index: bigint, betIds: bigint[],
 *   settled: boolean | null}>} `settled` is false while any listed bet is still
 *   queued after the sweep, null when unreadable.
 */
export async function resolveBets({ index, betIds } = {}) {
  if (index == null) throw new Error('The bet index is required.');
  const idx = _uint48(index, 'The bet index');
  if (!Array.isArray(betIds) || betIds.length === 0) {
    throw new Error('betIds must be a non-empty array.');
  }
  // Coerce to BigInt[] — defense-in-depth + ABI compatibility.
  const ids = betIds.map((id) => {
    try { return BigInt(id); }
    catch (_e) { throw new Error('Each betId must be numeric.'); }
  });
  const provider = getProvider();
  const signer = provider ? await provider.getSigner() : null;
  if (!signer && !getActingAddress()) throw new Error('Wallet not connected.');

  if (signer) {
    const c = _buildContract(signer);
    const sim = await requireStaticCall(c, 'mineFlip', [], signer);
    if (!sim.ok) throw _structuredRevertError(sim.error, 'static-call mineFlip');
  }

  const receipt = await sendTx(
    async (s) => {
      const c = _buildContract(s);
      return c.mineFlip({ gasLimit: await mineFlipGasLimit(c) });
    },
    'Settle degenerette bet',
  );
  let settled = null;
  try {
    const words = await Promise.all(ids.map((betId) => readBetInfo({ index: idx, betId })));
    settled = words.some((word) => word == null) ? null : words.every((word) => word === 0n);
  } catch (_e) { /* the panel's own poll stays authoritative */ }
  return { receipt, index: idx, betIds: ids, settled };
}

/**
 * Authoritative pending-state read: the queued word at (index, betId). The
 * contract zeroes the slot before emitting its resolution, so zero means the
 * bet has settled (or never existed). `null` means the RPC/test seam cannot
 * answer.
 */
export async function readBetInfo({ index, betId } = {}) {
  if (index == null || betId == null) return null;
  const provider = _readProvider();
  if (!provider) return null;
  const contract = _buildContract(provider);
  if (typeof contract.degeneretteBetInfo !== 'function') return null;
  return BigInt(await contract.degeneretteBetInfo(BigInt(index), BigInt(betId)));
}

/**
 * Side-effect-free readiness probe: true once the index's lootbox RNG word has
 * landed (read from storage, lootbox.js) and the first id is still queued —
 * exactly when the in-order sweep can settle it. There is no settle door to
 * simulate since audit 2525eb7fd.
 */
export async function canResolveBets({ index, betIds } = {}) {
  if (index == null || !Array.isArray(betIds) || betIds.length === 0) return false;
  const provider = _readProvider();
  if (!provider) return false;
  let ids;
  let idx;
  try {
    idx = _uint48(index, 'The bet index');
    ids = betIds.map((id) => BigInt(id));
  } catch (_e) { return false; }
  try {
    const [worded, packed] = await Promise.all([
      readLootboxIndexWorded(idx, { provider }),
      readBetInfo({ index: idx, betId: ids[0] }),
    ]);
    return worded === true && packed != null && packed !== 0n;
  } catch (_e) {
    return false;
  }
}

const REPLAY_LOG_CHUNK_BLOCKS = 1800;
const REPLAY_LOG_CHUNK_LIMIT = 10;

function _resolvedEntryFromArgs(args, fallback = {}, log = null, receipt = null, packed = null) {
  const a = args || [];
  const spinsRaw = a.spins ?? a[5];
  const spins = decodeDegeneretteSpins(spinsRaw);
  const transactionHash = String(
    log?.transactionHash || receipt?.hash || receipt?.transactionHash || '',
  ).toLowerCase() || null;
  return {
    player: String(fallback.player ?? a.player ?? a[0] ?? ''),
    index: BigInt(a.index ?? a[1] ?? fallback.index ?? 0),
    betId: BigInt(a.betId ?? a[2] ?? fallback.betId ?? 0),
    spinCount: BigInt(spins ? spins.length : 0),
    totalPayout: packed == null ? BigInt(a.totalPayout ?? a[3] ?? 0)
      : degeneretteTotalPayoutFromChain(a.totalPayout ?? a[3] ?? 0, packed),
    resultTraits: BigInt(a.resultTraits ?? a[4] ?? 0),
    spins: spins || [],
    spinsData: spinsRaw == null ? null : String(spinsRaw),
    transactionHash,
    blockNumber: log?.blockNumber ?? null,
    logIndex: log?.index ?? log?.logIndex ?? null,
  };
}

/**
 * Recover an already-settled bet directly from its chain events. All three of
 * DegeneretteResolved's keys (player, index, betId) are indexed topics, so the
 * backwards scan is exact and stays below the public RPC's block-range cap.
 * Pass the bet word as `packedData` when known; otherwise the same scan looks
 * for the bet's DegeneretteBetPlaced to price the spins.
 *
 * `receipt` is the settlement receipt NARROWED to this bet's own logs
 * (degeneretteSettlementReceipt): a keeper sweep settles many bets and opens
 * many boxes in one transaction.
 *
 * @returns {Promise<{
 *   resolved: {player:string,index:bigint,betId:bigint,spinCount:bigint,totalPayout:bigint,resultTraits:bigint},
 *   spins: Array<{player:string,betId:bigint,spinIndex:bigint,playerTraits:bigint,matches:bigint,payout:bigint}>,
 *   packedData: bigint,
 *   receipt?: import('ethers').TransactionReceipt|null
 * }|null>}
 */
export async function readResolvedBet({ player, index, betId, packedData = null } = {}) {
  const owner = player || getActingAddress();
  if (!owner || index == null || betId == null) return null;
  let id;
  let idx;
  try { id = BigInt(betId); idx = BigInt(index); } catch (_e) { return null; }
  const key = `${String(owner).toLowerCase()}:${idx}:${id}`;
  if (_resolvedBetCache.has(key)) return _resolvedBetCache.get(key);
  if (_resolvedBetInflight.has(key)) return _resolvedBetInflight.get(key);
  const request = _readResolvedBetUncached({ player: owner, index: idx, betId: id, packedData }).then((value) => {
    if (value) _resolvedBetCache.set(key, value);
    return value;
  }).finally(() => {
    if (_resolvedBetInflight.get(key) === request) _resolvedBetInflight.delete(key);
  });
  _resolvedBetInflight.set(key, request);
  return request;
}

async function _readResolvedBetUncached({ player: owner, index: idx, betId: id, packedData } = {}) {
  const provider = _readProvider();
  if (!provider || typeof provider.getBlockNumber !== 'function') return null;
  const contract = _buildContract(provider);
  if (typeof contract?.queryFilter !== 'function'
    || typeof contract?.filters?.DegeneretteResolved !== 'function') return null;
  let packed = null;
  try { if (packedData != null && BigInt(packedData) > 0n) packed = BigInt(packedData); } catch (_e) { packed = null; }
  const canFindPlacement = typeof contract?.filters?.DegeneretteBetPlaced === 'function';

  let head;
  try { head = Number(await readProviderBlockNumber(provider)); }
  catch (_e) { return null; }
  if (!Number.isFinite(head) || head < 0) return null;

  const ownerKey = hasWalletIds() ? await readWalletId(owner, { provider }) : owner;
  if (ownerKey == null || ownerKey === 0) return null;
  let resolvedLog = null;
  // Placement precedes settlement, so keep walking back (within the same chunk
  // budget) after the settlement is found until the bet word is recovered.
  for (let i = 0; i < REPLAY_LOG_CHUNK_LIMIT * 2; i += 1) {
    const to = head - i * REPLAY_LOG_CHUNK_BLOCKS;
    if (to < 0) break;
    if (!resolvedLog && i >= REPLAY_LOG_CHUNK_LIMIT) break;
    const from = Math.max(0, to - REPLAY_LOG_CHUNK_BLOCKS + 1);
    const wantPlaced = packed == null && canFindPlacement;
    let resolvedLogs = [];
    let placedLogs = [];
    try {
      [resolvedLogs, placedLogs] = await Promise.all([
        resolvedLog
          ? Promise.resolve([])
          : contract.queryFilter(contract.filters.DegeneretteResolved(ownerKey, idx, id), from, to),
        wantPlaced
          ? contract.queryFilter(contract.filters.DegeneretteBetPlaced(ownerKey, idx, id), from, to)
          : Promise.resolve([]),
      ]);
    } catch (_e) {
      return null;
    }
    if (!resolvedLog && Array.isArray(resolvedLogs) && resolvedLogs.length > 0) {
      resolvedLog = resolvedLogs.at(-1);
    }
    if (packed == null && Array.isArray(placedLogs) && placedLogs.length > 0) {
      const a = placedLogs.at(-1)?.args || [];
      try { packed = BigInt(a.packed ?? a[3] ?? 0); } catch (_e) { packed = null; }
      if (packed === 0n) packed = null;
    }
    if (resolvedLog && (packed != null || !canFindPlacement)) break;
    if (from === 0) break;
  }
  if (!resolvedLog || packed == null) return null;

  const resolved = _resolvedEntryFromArgs(resolvedLog.args, { player: owner, index: idx, betId: id }, resolvedLog, null, packed);
  const spins = degeneretteSpinResults(resolved, packed);
  const bet = decodeDegeneretteBetWord(packed);
  // A settled bet always carries one 5-byte group per placed spin. Refuse a
  // malformed/short payload instead of fabricating a shorter round.
  if (!spins || !bet || spins.length !== bet.spinCount) return null;
  let receipt = null;
  const transactionHash = resolved.transactionHash;
  if (transactionHash && typeof provider.getTransactionReceipt === 'function') {
    try {
      const full = await readTransactionReceipt(transactionHash, { provider });
      await prepareWalletReceipt(full);
      receipt = degeneretteSettlementReceipt(full, {
        player: owner, index: idx, betId: id, packedData: packed,
      });
    } catch (_e) { receipt = null; }
  }
  return { resolved, spins, receipt, transactionHash, packedData: packed };
}

// ---------------------------------------------------------------------------
// Settlement receipt narrowing. A mineFlip() sweep settles every
// bet at an index — many owners — right after opening that index's boxes, all
// in one transaction. Each bet's own logs are contiguous: any PayoutCapped, then
// its single direct Luckbox (LootBoxOpened at index 0 plus that box's legs and
// WWXRP/FLIP flushes), then its DegeneretteResolved, then — only if the bet
// armed a biggest-spin record — one type-3 BoxSpin. Walk back from the bet's
// own DegeneretteResolved to the nearest boundary (another bet's settlement, a
// record chain, another player's GAME log, or a human box at a real index) and
// forward over its record BoxSpin. A FLIP bet, or an ETH bet with no spin above
// 3× its stake and no pool cap, has no direct box at all, so nothing before its
// settlement is attributed to it.
// ---------------------------------------------------------------------------

function RESOLVED_TOPIC() { return hasWalletIds() ? _interface().getEvent('DegeneretteResolved').topicHash.toLowerCase() : ethers.id('DegeneretteResolved(address,uint32,uint64,uint256,uint32,bytes)').toLowerCase(); }
function BOX_SPIN_TOPIC() { return ethers.id(hasWalletIds() ? 'BoxSpin(uint32,uint64,uint256,uint256,uint256)' : 'BoxSpin(address,uint64,uint256,uint256,uint256)').toLowerCase(); }
function LOOTBOX_OPENED_TOPIC() { return ethers.id(hasWalletIds() ? 'LootBoxOpened(uint32,uint48,uint256,uint24,uint32,uint256,bool)' : 'LootBoxOpened(address,uint48,uint256,uint24,uint32,uint256,bool)').toLowerCase(); }
function PAYOUT_CAPPED_TOPIC() { return ethers.id(hasWalletIds() ? 'PayoutCapped(uint32,uint256,uint256)' : 'PayoutCapped(address,uint256,uint256)').toLowerCase(); }
function AFKING_DELIVERED_TOPIC() { return ethers.id(hasWalletIds() ? 'AfkingDelivered(uint32,uint256)' : 'AfkingDelivered(address,uint256)').toLowerCase(); }
function PRESALE_OPENED_TOPIC() { return ethers.id(hasWalletIds() ? 'PresaleBoxOpened(uint32,uint48,uint256,uint256,uint256,uint256,bool,uint32,uint32)' : 'PresaleBoxOpened(address,uint48,uint256,uint256,uint256,uint256,bool,uint32,uint32)').toLowerCase(); }

function _topicWord(value) {
  return `0x${BigInt(value).toString(16).padStart(64, '0')}`;
}

function _addressTopic(address) {
  return `0x${String(address || '').toLowerCase().replace(/^0x/, '').padStart(64, '0')}`;
}

function _isRecordBoxSpin(log) {
  try {
    const betId = BigInt(`0x${String(log?.data || '').replace(/^0x/, '').slice(0, 64) || '0'}`);
    return (betId >> 63n) === 1n && ((betId >> 60n) & 7n) === 3n;
  } catch (_e) {
    return false;
  }
}

/** True when a bet's settled spins leave a direct Luckbox (ETH, some spin > 3× stake). */
export function degeneretteExpectsLuckbox(packed, spinRows = null) {
  const bet = decodeDegeneretteBetWord(packed);
  if (!bet || bet.currency !== DEGENERETTE_CURRENCY.ETH) return false;
  const threeBet = bet.amountPerSpin * 3n;
  return (Array.isArray(spinRows) ? spinRows : []).some((row) => {
    try { return BigInt(row?.payout ?? 0) > threeBet; } catch (_e) { return false; }
  });
}

/**
 * Narrow a settlement receipt to one bet's own logs. Returns a shallow receipt
 * copy whose `logs` hold only that bet's Luckbox window and record-bounty
 * spins, or null when the receipt carries no settlement for that bet.
 */
export function degeneretteSettlementReceipt(receipt, {
  player, index, betId, packedData = null, expectLuckbox = null, game = CONTRACTS.GAME,
} = {}) {
  const logs = Array.isArray(receipt?.logs) ? receipt.logs : null;
  if (!logs || !player || index == null || betId == null) return null;
  const gameAddress = String(game || '').toLowerCase();
  const playerId = hasWalletIds() ? (packedData != null ? Number(BigInt(packedData) & 0xffffffffn) : cachedWalletId(player)) : null;
  if (hasWalletIds() && !playerId) return null;
  const playerTopic = hasWalletIds() ? _topicWord(playerId) : _addressTopic(player);
  let indexTopic;
  let betTopic;
  try { indexTopic = _topicWord(index); betTopic = _topicWord(betId); } catch (_e) { return null; }
  const isGame = (log) => !gameAddress || String(log?.address || '').toLowerCase() === gameAddress;
  const topic = (log, i) => String(log?.topics?.[i] || '').toLowerCase();
  const target = logs.findIndex((log) => isGame(log)
    && topic(log, 0) === RESOLVED_TOPIC()
    && topic(log, 1) === playerTopic
    && topic(log, 2) === indexTopic
    && topic(log, 3) === betTopic);
  if (target < 0) return null;

  let start = target;
  for (let p = target - 1; p >= 0; p -= 1) {
    const log = logs[p];
    if (!isGame(log)) { start = p; continue; }
    const t0 = topic(log, 0);
    if (t0 === RESOLVED_TOPIC() || t0 === AFKING_DELIVERED_TOPIC() || t0 === PRESALE_OPENED_TOPIC()) break;
    if (topic(log, 1) !== playerTopic) break;
    if (t0 === LOOTBOX_OPENED_TOPIC() && BigInt(topic(log, 2) || '0x0') !== 0n) break;
    if (t0 === BOX_SPIN_TOPIC() && _isRecordBoxSpin(log)) break;
    start = p;
  }
  let boxLogs = logs.slice(start, target);
  let expect = expectLuckbox;
  if (expect == null) {
    const resolvedArgs = (() => {
      try { return _interface().parseLog(logs[target])?.args ?? null; } catch (_e) { return null; }
    })();
    const entry = resolvedArgs ? _resolvedEntryFromArgs(resolvedArgs) : null;
    expect = packedData == null
      ? true
      : degeneretteExpectsLuckbox(packedData, entry ? degeneretteSpinResults(entry, packedData) : null);
  }
  const capped = boxLogs.some((log) => isGame(log) && topic(log, 0) === PAYOUT_CAPPED_TOPIC());
  if (!expect && !capped) boxLogs = [];

  const recordLogs = [];
  for (let p = target + 1; p < logs.length; p += 1) {
    const log = logs[p];
    if (!isGame(log)) continue;
    if (topic(log, 0) === BOX_SPIN_TOPIC() && topic(log, 1) === playerTopic && _isRecordBoxSpin(log)) {
      recordLogs.push(log);
      continue;
    }
    break;
  }
  return { ...receipt, logs: [...boxLogs, logs[target], ...recordLogs] };
}

// ---------------------------------------------------------------------------
// parseBetPlacedFromReceipt — extracts {player, index, betId, packed}.
// CF-05 receipt-log-first pattern (Phase 60 D-03).
// ---------------------------------------------------------------------------

/**
 * @param {import('ethers').TransactionReceipt | null | undefined} receipt
 * @param {import('ethers').Contract} contract
 * @returns {Array<{player: string, index: bigint, betId: bigint, packed: bigint}>}
 */
export function parseBetPlacedFromReceipt(receipt, contract = receiptParser()) {
  const out = [];
  if (!receipt || !Array.isArray(receipt.logs)) return out;
  for (const log of receipt.logs) {
    try {
      const parsed = walletReceiptLog(log, contract.interface);
      if (parsed && parsed.name === 'DegeneretteBetPlaced') {
        out.push({
          player: String(parsed.args.player ?? parsed.args[0]),
          index: BigInt(parsed.args.index ?? parsed.args[1]),
          betId: BigInt(parsed.args.betId ?? parsed.args[2]),
          packed: BigInt(parsed.args.packed ?? parsed.args[3]),
        });
      }
    } catch (_e) {
      // skip non-matching logs
    }
  }
  return out;
}

/**
 * The biggest-spin record claim armed by a placement, in whole FLIP (token
 * wei), read off Coinflip's BigRecordUpdated in the placement receipt. Zero
 * when the placement did not claim the record pool. `paid` is a FLIP amount in
 * the deployment's raw units (whole since audit b05ea7c50).
 */
export function parseRecordStakeFromReceipt(receipt, player, { coinflip: coinflipAddress = CONTRACTS.COINFLIP } = {}) {
  if (!receipt || !Array.isArray(receipt.logs) || !player) return 0n;
  const want = String(player).toLowerCase();
  const coinflip = String(coinflipAddress || '').toLowerCase();
  const iface = _recordInterface();
  let stake = 0n;
  for (const log of receipt.logs) {
    if (coinflip && String(log?.address || '').toLowerCase() !== coinflip) continue;
    let parsed = null;
    try { parsed = walletReceiptLog(log, iface); } catch (_e) { parsed = null; }
    if (!parsed || parsed.name !== 'BigRecordUpdated') continue;
    if (BigInt(parsed.args.kind ?? parsed.args[0]) !== RECORD_KIND_SPIN) continue;
    if (String(parsed.args.player ?? parsed.args[1]).toLowerCase() !== want) continue;
    const paid = flipFromChain(parsed.args.paid ?? parsed.args[3] ?? 0);
    stake = (paid / TOKEN_WEI) * TOKEN_WEI;
  }
  return stake;
}

// ---------------------------------------------------------------------------
// parseBetResolvedFromReceipt — extracts DegeneretteResolved entries, one per
// settled bet, each with its decoded spins (payouts need the bet word:
// degeneretteSpinResults / parseSpinResultsFromReceipt).
// ---------------------------------------------------------------------------

/**
 * @param {import('ethers').TransactionReceipt | null | undefined} receipt
 * @param {{interface: {parseLog: Function}}} [contract]
 * @returns {Array<{player: string, index: bigint, betId: bigint, spinCount: bigint, totalPayout: bigint, resultTraits: bigint, spins: Array}>}
 */
export function parseBetResolvedFromReceipt(receipt, contract = receiptParser(), { packed = null } = {}) {
  const out = [];
  if (!receipt || !Array.isArray(receipt.logs)) return out;
  for (const log of receipt.logs) {
    try {
      const parsed = walletReceiptLog(log, contract.interface);
      if (parsed && parsed.name === 'DegeneretteResolved') {
        // The bet word (or a function of the entry) prices a FLIP bet's totalPayout.
        const entry = _resolvedEntryFromArgs(parsed.args, {}, log, receipt);
        const word = typeof packed === 'function' ? packed(entry) : packed;
        out.push(word == null ? entry : _resolvedEntryFromArgs(parsed.args, {}, log, receipt, word));
      }
    } catch (_e) {
      // skip
    }
  }
  return out;
}

// ---------------------------------------------------------------------------
// parseSpinResultsFromReceipt — per-spin rows for every DegeneretteResolved in
// the receipt, priced from the bet word(s). `packed` is either one bet word
// (applied to every settled bet — right for a single-bet settle) or a function
// (entry) → word. A bet whose word is unknown yields no rows.
// ---------------------------------------------------------------------------

/**
 * @param {import('ethers').TransactionReceipt | null | undefined} receipt
 * @param {{interface: {parseLog: Function}}} [contract]
 * @param {{packed?: bigint|string|function}} [options]
 * @returns {Array<{player: string, index: bigint, betId: bigint, spinIndex: bigint, playerTraits: bigint, matches: bigint, wilds: bigint, payout: bigint}>}
 */
export function parseSpinResultsFromReceipt(receipt, contract = receiptParser(), { packed = null } = {}) {
  const out = [];
  for (const entry of parseBetResolvedFromReceipt(receipt, contract, { packed })) {
    const word = typeof packed === 'function' ? packed(entry) : packed;
    const rows = degeneretteSpinResults(entry, word);
    if (rows) out.push(...rows);
  }
  return out;
}

